begin;create extension if not exists pgtap with schema extensions;select extensions.no_plan();
insert into auth.users(id)select('4a700000-0000-4000-8000-00000000000'||n)::uuid from generate_series(1,6)n;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at)select id,id,'totp','verified',now(),now()from auth.users where id::text like'4a700000-%';
insert into auth.sessions(id,user_id,factor_id,aal)select id,id,id,'aal2'from auth.users where id::text like'4a700000-%';
insert into public.team_profiles(id,full_name,is_active)select id,'Synthetic enquiry staff',id::text not like'%5'from auth.users where id::text like'4a700000-%';
insert into public.team_role_assignments select('4a700000-0000-4000-8000-00000000000'||v.n)::uuid,r.id from(values(1,'platform_owner'),(2,'content_community_lead'),(3,'operations_lead'),(4,'technical_lead'),(5,'operations_lead'))v(n,code)join public.roles r on r.code=v.code;
create function pg_temp.claims(n int,aal text default'aal2')returns text language sql as $$select json_build_object('sub','4a700000-0000-4000-8000-00000000000'||n,'role','authenticated','aal',aal,'session_id','4a700000-0000-4000-8000-00000000000'||n,'exp',extract(epoch from now()+interval'1 hour')::bigint)::text$$;
create function pg_temp.h(v text)returns text language sql as $$select encode(sha256(convert_to(v,'UTF8')),'hex')$$;
create function pg_temp.payload(c text)returns jsonb language sql as $$select jsonb_build_object('fullName','Synthetic Contact','email','synthetic@example.invalid','whatsapp',null,'category',c,'message','Private original enquiry must never appear in a technical brief.','consentVersion','contact-v1')$$;
create function pg_temp.submit(k text,c text)returns void language sql as $$select public.submit_contact_enquiry(pg_temp.payload(c),'BWEQ-'||md5(k),pg_temp.h(k),pg_temp.h(pg_temp.payload(c)::text),pg_temp.h('dedup:'||c),pg_temp.h('global'),pg_temp.h('email:'||k))$$;
create function pg_temp.id(c text)returns uuid language sql security definer set search_path=''as $$select id from business_private.contact_enquiries where category=c$$;
select extensions.ok(not has_table_privilege('authenticated','business_private.contact_enquiries','SELECT,INSERT,UPDATE,DELETE'),'no direct private enquiry CRUD');
select extensions.ok(not has_function_privilege('anon','public.list_contact_enquiries(text,text)','execute'),'anonymous inbox denied');
select extensions.ok(not has_function_privilege('authenticated','public.submit_contact_enquiry(jsonb,text,text,text,text,text,text)','execute'),'caller cannot impersonate ingress');
select extensions.ok(not has_function_privilege('service_role','public.manage_contact_enquiry(uuid,int,uuid,text,text,text)','execute'),'ingress cannot mutate staff workflow');
set local role service_role;select pg_temp.submit('general','general');select pg_temp.submit('business','partnership');select pg_temp.submit('technical','technical');
select extensions.lives_ok($$select pg_temp.submit('general','general')$$,'idempotent retry accepted');
select extensions.throws_ok($$select pg_temp.submit('general','other')$$,'PT409',null,'changed idempotent payload rejected');
select pg_temp.submit('duplicate','general');reset role;
select extensions.is((select count(*)from business_private.contact_enquiries where category='general'),1::bigint,'new key cannot duplicate identical enquiry within 24 hours');
select extensions.is((select department from business_private.contact_enquiries where category='general'),'communications','general routes to Divine department');
select extensions.is((select department from business_private.contact_enquiries where category='partnership'),'operations','business routes to Nateu department');
select extensions.is((select department from business_private.contact_enquiries where category='technical'),'communications','technical starts in triage, not Kevin inbox');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(2,'aal1'),true);
select extensions.throws_ok($$select public.list_contact_enquiries()$$,'42501',null,'AAL1 denied');
select set_config('request.jwt.claims',pg_temp.claims(5),true);select extensions.throws_ok($$select public.list_contact_enquiries()$$,'42501',null,'inactive staff denied');
select set_config('request.jwt.claims',pg_temp.claims(6),true);select extensions.throws_ok($$select public.list_contact_enquiries()$$,'42501',null,'unassigned AAL2 denied');
select set_config('request.jwt.claims',pg_temp.claims(2),true);select extensions.is(jsonb_array_length(public.list_contact_enquiries()),2,'Divine sees only Communications');
select extensions.throws_ok($$select public.get_contact_enquiry(pg_temp.id('partnership'))$$,'42501',null,'Divine cannot guess Operations enquiry id');
select extensions.ok(not app_private.has_permission('inquiries.read'),'new rights do not reveal project requests');
select public.manage_contact_enquiry(pg_temp.id('technical'),1,'4a700000-1000-4000-8000-000000000001','note','','Private handler note');
select public.manage_contact_enquiry(pg_temp.id('technical'),2,'4a700000-1000-4000-8000-000000000002','refer','technology','Minimal technical question only');
select extensions.lives_ok($$select public.manage_contact_enquiry(pg_temp.id('technical'),2,'4a700000-1000-4000-8000-000000000002','refer','technology','Minimal technical question only')$$,'repeated operation does not duplicate referral');
select extensions.throws_ok($$select public.manage_contact_enquiry(pg_temp.id('technical'),3,gen_random_uuid(),'refer','technology','Second brief')$$,'23505',null,'second active referral rejected atomically');
select extensions.throws_ok($$select public.manage_contact_enquiry(pg_temp.id('technical'),1,gen_random_uuid(),'status','in_progress','Stale edit')$$,'PT409',null,'stale update fails');
select extensions.throws_ok($$select public.manage_contact_enquiry(pg_temp.id('technical'),3,gen_random_uuid(),'status','resolved','Skip workflow')$$,null,null,'invalid status transition rejected');
select public.manage_contact_enquiry(pg_temp.id('technical'),3,'4a700000-1000-4000-8000-000000000003','status','in_progress','Starting technical triage');
select set_config('request.jwt.claims',pg_temp.claims(4),true);
select extensions.throws_ok($$select public.list_contact_enquiries()$$,'42501',null,'Kevin has no unrestricted inbox');
select extensions.throws_ok($$select public.get_contact_enquiry(pg_temp.id('technical'))$$,'42501',null,'Kevin cannot read original by UUID');
select extensions.is(jsonb_array_length(public.list_enquiry_assessments()),1,'Kevin sees active shared brief');
select extensions.ok(position('Private original'in public.list_enquiry_assessments()::text)=0 and position('synthetic@example'in public.list_enquiry_assessments()::text)=0 and position('Private handler note'in public.list_enquiry_assessments()::text)=0,'brief projection excludes original, contact and internal note');
select public.respond_enquiry_assessment((public.list_enquiry_assessments()->0->>'id')::uuid,1,'4a700000-1000-4000-8000-000000000004','Synthetic technical assessment');
select extensions.is(public.list_enquiry_assessments()->0->'responses'->0->>'body','Synthetic technical assessment','assessment retained');
select set_config('request.jwt.claims',pg_temp.claims(3),true);select extensions.is(jsonb_array_length(public.list_contact_enquiries()),1,'Nateu sees only Operations');
select extensions.throws_ok($$select public.get_contact_enquiry(pg_temp.id('general'))$$,'42501',null,'Operations cannot guess Communications enquiry');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.ok(position('Synthetic technical assessment'in public.get_contact_enquiry(pg_temp.id('technical'))::text)>0,'handler sees assessment response');
select public.manage_contact_enquiry(pg_temp.id('technical'),4,'4a700000-1000-4000-8000-000000000005','revoke',public.get_contact_enquiry(pg_temp.id('technical'))->'referrals'->0->>'id','Assessment complete; revoke access');
select set_config('request.jwt.claims',pg_temp.claims(4),true);select extensions.is(jsonb_array_length(public.list_enquiry_assessments()),0,'revocation removes technical access');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
select public.manage_contact_enquiry(pg_temp.id('general'),1,'4a700000-1000-4000-8000-000000000006','route','operations','Commercial follow-up needed');
select extensions.throws_ok($$select public.get_contact_enquiry(pg_temp.id('general'))$$,'42501',null,'previous department loses transferred access');
select set_config('request.jwt.claims',pg_temp.claims(3),true);select extensions.is(public.get_contact_enquiry(pg_temp.id('general'))->>'department','operations','new department receives full referred enquiry');
select public.manage_contact_enquiry(pg_temp.id('general'),2,'4a700000-1000-4000-8000-000000000007','manual_email','','Staff attests external dispatch; not a delivery receipt');
select extensions.lives_ok($$select public.manage_contact_enquiry(pg_temp.id('general'),2,'4a700000-1000-4000-8000-000000000007','manual_email','','Staff attests external dispatch; not a delivery receipt')$$,'manual dispatch confirmation is idempotent');
select extensions.throws_ok($$select public.manage_contact_enquiry(pg_temp.id('general'),3,gen_random_uuid(),'manual_whatsapp','','No phone exists')$$,null,null,'no unsupported WhatsApp dispatch record');
select set_config('request.jwt.claims',pg_temp.claims(1),true);select extensions.is(jsonb_array_length(public.list_contact_enquiries()),3,'Owner sees all departments');
reset role;select extensions.is((select count(*)from business_private.enquiry_activity where kind='manual_email'),1::bigint,'one dispatch history entry');
select extensions.is((select count(*)from public.audit_logs where action='enquiry.manual_email'and actor_id='4a700000-0000-4000-8000-000000000003'),1::bigint,'one dispatch audit event');
select extensions.ok((select count(*)from public.audit_logs where action like'enquiry.%'and actor_id::text like'4a700000-%')>=7,'sensitive actions audited without message bodies');
select * from extensions.finish();rollback;
